#include "warmdebt.hpp"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{if(argc==1||(argc==2&&std::string(argv[1])=="demo")){std::cout<<warm::demo()<<'\n';return 0;}if(argc!=3||std::string(argv[1])!="replay")throw std::runtime_error("usage: warmdebt [demo | replay TRACE]");std::ifstream f(argv[2]);if(!f)throw std::runtime_error("cannot open trace");std::vector<warm::Request> t;std::string line;while(std::getline(f,line)){if(line.empty())continue;std::istringstream in(line);warm::Request q;std::string extra;if(!(in>>q.arrival>>q.service>>q.budget)||(in>>extra))throw std::runtime_error("trace lines: arrival service latency_budget");if(t.size()==10000)throw std::runtime_error("trace exceeds bound");t.push_back(q);}std::cout<<"{\"kind\":\"synthetic_assumption_trace_replay\",\"policy\":"<<warm::json(warm::simulate(t,warm::Policy::margin_schedule,{6,9,12},100,{3,5,4},2,1000))<<"}\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
